import os

final class FileCache: Sendable {
    private let strategy = OSAllocatedUnfairLock(initialState: Inner())

    func find(_ path: String) -> String? {
        strategy.withLock { state in      // acquire, run closure, release
            state.findLocked(path)
        }
    }
}
